"scripts": {
    "build": "vite build",
    "dev": "vite",
    "lint": "eslint resources/",
    "lint:fix": "eslint resources/ --fix",
    "test:e2e": "npm run build && playwright test"
},
"devDependencies": {
    "@eslint/js": "^10.0.1",

import { apiGet, apiPatch, apiPost } from './client';

export async function getCompanies() {
    const payload = await apiGet('/api/v1/companies');

    return payload.data ?? [];
}

export async function getCompanyEmployees(companyId) {
    const payload = await apiGet(`/api/v1/companies/${companyId}/employees`);

    return payload.data ?? [];
}

export async function getCompanyProjects(companyId, employeeId = null) {
    const params = new URLSearchParams();

    if (employeeId) {
        params.set('filter[employee_id]', employeeId);
    }

    const query = params.toString();
    const payload = await apiGet(`/api/v1/companies/${companyId}/projects${query ? `?${query}` : ''}`);

    return payload.data ?? [];
}

export async function getCompanyTasks(companyId) {
    const payload = await apiGet(`/api/v1/companies/${companyId}/tasks`);

    return payload.data ?? [];
}

export async function createTimeEntries(entries) {
    const payload = await apiPost('/api/v1/time-entries', { entries });

    return payload.data ?? [];
}

export async function updateTimeEntry(entryId, entry) {
    const payload = await apiPatch(`/api/v1/time-entries/${entryId}`, entry);

    return payload.data ?? null;
}

export async function getTimeEntries(options = {}) {
    const normalizedOptions = typeof options === 'string'
        ? { companyId: options }
        : options ?? {};
    const params = new URLSearchParams();

    if (normalizedOptions.companyId) {
        params.set('filter[company_id]', normalizedOptions.companyId);
    }

    if (normalizedOptions.search) {
        params.set('filter[search]', normalizedOptions.search);
    }

    if (normalizedOptions.page) {
        params.set('page', normalizedOptions.page);
    }

    if (normalizedOptions.perPage) {
        params.set('per_page', normalizedOptions.perPage);
    }

    const query = params.toString();
    const payload = await apiGet(`/api/v1/time-entries${query ? `?${query}` : ''}`);

    return {
        entries: payload.data ?? [],
        links: payload.links ?? {},
        meta: payload.meta ?? {},
    };
}

import { nextTick, reactive } from 'vue';

export const spreadsheetColumns = ['company', 'date', 'employee', 'project', 'task', 'hours'];

export function useSpreadsheetNavigation(rowCount, addRow) {
    const activeCell = reactive({
        row: 0,
        column: 0,
    });
    const cellRefs = new Map();

    function cellKey(row, column) {
        return `${row}:${column}`;
    }

    function setCellRef(row, column, element) {
        const key = cellKey(row, column);

        if (element) {
            cellRefs.set(key, element);
            return;
        }

        cellRefs.delete(key);
    }

    async function focusCell(row, column) {
        await nextTick();

        const target = cellRefs.get(cellKey(row, column));

        if (typeof target?.focus === 'function') {
            target.focus();
            return;
        }

        if (typeof target?.$el?.focus === 'function') {
            target.$el.focus();
            return;
        }

        target?.$el?.querySelector?.('button,input,[tabindex]')?.focus();
    }

    function setActiveCell(row, column, options = {}) {
        activeCell.row = Math.max(0, Math.min(row, rowCount.value - 1));
        activeCell.column = Math.max(0, Math.min(column, spreadsheetColumns.length - 1));

        if (options.focus) {
            focusCell(activeCell.row, activeCell.column);
        }
    }

    function handleCellKeydown(event, row, column) {
        if (['Enter', ' ', 'F2'].includes(event.key) && event.currentTarget.dataset.editor === 'trigger') {
            return;
        }

        if (!['Tab', 'Enter', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) {
            return;
        }

        event.preventDefault();

        if (event.key === 'Tab') {
            const direction = event.shiftKey ? -1 : 1;
            const nextColumn = column + direction;

            if (nextColumn >= spreadsheetColumns.length) {
                if (row === rowCount.value - 1) {
                    addRow();
                }
                setActiveCell(row + 1, 0, { focus: true });
                return;
            }

            if (nextColumn < 0) {
                setActiveCell(row - 1, spreadsheetColumns.length - 1, { focus: true });
                return;
            }

            setActiveCell(row, nextColumn, { focus: true });
            return;
        }

        if (event.key === 'Enter') {
            setActiveCell(row + 1, column, { focus: true });
            return;
        }

        const movements = {
            ArrowLeft: [0, -1],
            ArrowRight: [0, 1],
            ArrowUp: [-1, 0],
            ArrowDown: [1, 0],
        };
        const [rowDelta, columnDelta] = movements[event.key];
        setActiveCell(row + rowDelta, column + columnDelta, { focus: true });
    }

    return {
        activeCell,
        handleCellKeydown,
        setCellRef,
        setActiveCell,
    };
}

import { expect, test } from '@playwright/test';

test.beforeEach(async ({ page }) => {
    await page.goto('/entries/history');
    await expect(page.getByRole('heading', { name: 'History' })).toBeVisible();
});

test('lists time entries from the history API', async ({ page }) => {
    await expect(page.getByRole('cell', { name: 'Acme Operations' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Ava Chen' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Website Redesign' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Development' }).first()).toBeVisible();
    await expect(page.getByText(/entries$/).first()).toBeVisible();
});

test('filters history when the global company scope changes', async ({ page }) => {
    await page.getByRole('button', { name: 'All companies' }).click();
    await page.getByRole('option', { name: 'Globex Services' }).click();

    await expect(page.getByRole('cell', { name: 'Globex Services' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Acme Operations' })).toHaveCount(0);
    await expect(page.getByText('Company scope')).toBeVisible();
});

test('searches history and sorts the visible rows', async ({ page }) => {
    await page.getByPlaceholder('Search company, employee, project, or task').fill('Website');

    await expect(page.getByRole('cell', { name: 'Website Redesign' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Data Migration' })).toHaveCount(0);

    await page.getByRole('button', { name: 'Hours' }).click();
    await expect(page.getByRole('button', { name: 'Hours' })).toBeVisible();
});

test('edits an existing history entry', async ({ page }) => {
    await page.getByPlaceholder('Search company, employee, project, or task').fill('Cora');
    await expect(page.getByRole('cell', { name: 'Cora Diaz' }).first()).toBeVisible();

    await page.getByRole('button', { name: 'Edit Cora Diaz entry' }).click();
    await expect(page.getByRole('dialog', { name: 'Edit time entry' })).toBeVisible();

    await page.getByLabel('Hours').fill('6.25');
    await page.getByRole('button', { name: 'Save changes' }).click();

    await expect(page.getByText('Time entry updated.')).toBeVisible();
    await expect(page.getByRole('dialog', { name: 'Edit time entry' })).toHaveCount(0);
    const updatedRow = page.getByRole('row').filter({ has: page.getByRole('cell', { name: 'Cora Diaz' }) }).first();

    await expect(updatedRow.getByRole('cell', { name: '6.25' })).toBeVisible();
});

test('shows a newly submitted entry after switching to history', async ({ page }) => {
    const { entryDate, taskName } = await unusedWebsiteEntrySlot(page);
    const entryDateDisplay = new Date(`${entryDate}T00:00:00`).toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
    });

    await page.goto('/entries/new');
    await expect(page.getByRole('heading', { name: 'New Entries' })).toBeVisible();

    const firstRow = page.locator('tbody tr').first();

    await selectSpreadsheetOption(page, firstRow, 'Select company', 'Acme Operations');
    await selectDate(page, firstRow, entryDate);
    await selectSpreadsheetOption(page, firstRow, 'Select employee', 'Ben Carter');
    await selectSpreadsheetOption(page, firstRow, 'Select project', 'Website Redesign');
    await selectSpreadsheetOption(page, firstRow, 'Select task', taskName);
    await firstRow.getByPlaceholder('0.00').fill('7.75');
    await page.getByRole('button', { name: 'Submit batch' }).click();

    await expect(page.getByText('Time entries saved.').first()).toBeVisible();
    await expect(page.getByText('1 entry added to history.')).toBeVisible();
    await page.getByRole('link', { name: 'History' }).click();

    await expect(page.getByRole('heading', { name: 'History' })).toBeVisible();
    const createdRow = page.getByRole('row').filter({ has: page.getByRole('cell', { name: entryDateDisplay }) }).first();

    await expect(createdRow.getByRole('cell', { name: 'Ben Carter', exact: true })).toBeVisible();
    await expect(createdRow.getByRole('cell', { name: taskName })).toBeVisible();
    await expect(createdRow.getByRole('cell', { name: '7.75' })).toBeVisible();
});

async function unusedWebsiteEntrySlot(page) {
    const response = await page.request.get('/api/v1/time-entries?filter[search]=Ben%20Carter&per_page=50');
    const payload = await response.json();
    const used = new Set((payload.data ?? [])
        .filter((entry) => entry.company?.name === 'Acme Operations' && entry.project?.name === 'Website Redesign')
        .map((entry) => `${entry.entry_date}:${entry.task?.name}`));
    const taskNames = ['Planning', 'Development', 'Review'];
    const today = new Date();

    for (let day = 1; day <= 28; day += 1) {
        const entryDate = formatDate(new Date(today.getFullYear(), today.getMonth(), day));

        for (const taskName of taskNames) {
            if (!used.has(`${entryDate}:${taskName}`)) {
                return { entryDate, taskName };
            }
        }
    }

    throw new Error('No unused current-month Website Redesign slot is available for Ben Carter.');
}

async function selectSpreadsheetOption(page, row, triggerName, optionName) {
    await row.getByRole('button', { name: triggerName }).click();
    await page.getByRole('option', { name: optionName }).click();
}

async function selectDate(page, row, date) {
    await row.getByRole('button', { name: 'Set date' }).click();
    await page.locator(`[data-date="${date}"]`).click();
}

function formatDate(date) {
    const year = `${date.getFullYear()}`;
    const month = `${date.getMonth() + 1}`.padStart(2, '0');
    const day = `${date.getDate()}`.padStart(2, '0');

    return `${year}-${month}-${day}`;
}

import { expect, test } from '@playwright/test';

const today = new Date();
const todayDate = formatDate(today);
const todayDay = `${today.getDate()}`;
const nextDayDate = formatDate(addDays(today, 1));
const nextWeekDate = formatDate(addDays(today, 8));
const weekStartDate = formatDate(addDays(addDays(today, 8), -addDays(today, 8).getDay()));
const weekEndDate = formatDate(addDays(addDays(today, 8), 6 - addDays(today, 8).getDay()));
const nextMonthSameDayDate = formatDate(shiftMonth(parseDate(weekEndDate), 1));
const nextMonthSameDayDisplay = formatDisplayDate(parseDate(nextMonthSameDayDate));

test.beforeEach(async ({ page }) => {
    await page.goto('/entries/new');
    await expect(page.getByRole('heading', { name: 'New Entries' })).toBeVisible();
});

test('cell editor commits advance focus through company, date, and employee cells', async ({ page }) => {
    const firstRow = page.locator('tbody tr').first();

    await firstRow.getByRole('button', { name: 'Select company' }).focus();
    await page.keyboard.press('Enter');
    await page.getByRole('option', { name: 'Acme Operations' }).click();

    await expect(firstRow.getByRole('button', { name: 'Set date' })).toBeFocused();

    await page.keyboard.press('Enter');
    const selectedDay = page.locator(`[data-date="${todayDate}"]`).filter({ hasText: new RegExp(`^${todayDay}$`) });
    await expect(selectedDay).toBeFocused();

    await page.keyboard.press('ArrowRight');
    await expect(page.locator(`[data-date="${nextDayDate}"]`)).toBeFocused();

    await page.keyboard.press('ArrowDown');
    await expect(page.locator(`[data-date="${nextWeekDate}"]`)).toBeFocused();

    await page.keyboard.press('Home');
    await expect(page.locator(`[data-date="${weekStartDate}"]`)).toBeFocused();

    await page.keyboard.press('End');
    await expect(page.locator(`[data-date="${weekEndDate}"]`)).toBeFocused();

    await page.keyboard.press('PageDown');
    await expect(page.locator(`[data-date="${nextMonthSameDayDate}"]`)).toBeFocused();

    await page.keyboard.press('Enter');
    await expect(firstRow.getByRole('button', { name: nextMonthSameDayDisplay })).toBeVisible();
    await expect(firstRow.getByRole('button', { name: 'Select employee' })).toBeFocused();

    await page.keyboard.press('Enter');
    await page.getByRole('option', { name: 'Ava Chen' }).click();
    await expect(firstRow.getByRole('button', { name: 'Select project' })).toBeFocused();
});

test('tab exits an open picker into the next spreadsheet cell', async ({ page }) => {
    const firstRow = page.locator('tbody tr').first();

    await firstRow.getByRole('button', { name: 'Select company' }).focus();
    await page.keyboard.press('Enter');
    await page.getByRole('option', { name: 'Acme Operations' }).click();

    await page.keyboard.press('Enter');
    await expect(page.locator(`[data-date="${todayDate}"]`)).toBeFocused();

    await page.keyboard.press('Tab');
    await expect(firstRow.getByRole('button', { name: 'Select employee' })).toBeFocused();
});

test('spreadsheet actions are available through keyboard shortcuts', async ({ page }) => {
    const firstRow = page.locator('tbody tr').first();

    await selectSpreadsheetOption(page, firstRow, 'Select company', 'Acme Operations');
    await firstRow.getByRole('button', { name: 'Acme Operations' }).focus();

    await page.keyboard.press('Control+D');
    await expect(page.getByText('3 rows')).toBeVisible();
    await expect(page.locator('tbody tr').nth(1).getByPlaceholder('0.00')).toBeFocused();

    await page.keyboard.press('Control+Shift+Enter');
    await expect(page.getByText('4 rows')).toBeVisible();
    await expect(page.locator('tbody tr').nth(3).getByRole('button', { name: 'Select company' })).toBeFocused();
});

test('global shortcuts switch tabs and focus the spreadsheet', async ({ page }) => {
    const legend = page.getByLabel('Keyboard shortcuts');

    await expect(legend.getByText('Shortcuts')).toBeVisible();
    await expect(legend.getByText('New entries', { exact: true })).toBeVisible();
    await expect(legend.getByText('History', { exact: true })).toBeVisible();
    await expect(legend.getByText('Spreadsheet', { exact: true })).toBeVisible();

    await page.keyboard.press('Alt+H');
    await expect(page.getByRole('heading', { name: 'History' })).toBeVisible();

    await page.keyboard.press('Alt+N');
    await expect(page.getByRole('heading', { name: 'New Entries' })).toBeVisible();

    await page.keyboard.press('Alt+E');
